// València's trees in the detailed city, generated by tools/realism/build-trees.py from the municipal tree inventory
// (Ajuntament de València, Arbratge / Arbolado, CC BY 4.0) and their height and crown measured in PNOA-LiDAR 2023
// (CNIG, CC BY 4.0; tools/realism/tree-lidar.py). VLT2 (gzipped) = magic, u32 count, u16 n, n bytes of JSON
// [[kind, archetype], ...], then 8-byte records [i16 x, i16 z (world, 0.25 m units), u8 kind, u8 height x 8,
// u8 crown diameter x 8, u8 flags (1: in a sidewalk pit, 2: height measured, 4: crown measured)].
const response = await fetch(new URL('./vlc-trees.bin.gz', import.meta.url));
if (!response.ok) throw new Error(`Tree data request failed: ${response.status}`);
const body = new Uint8Array(await response.arrayBuffer());
const data = body[0] === 0x1f && body[1] === 0x8b
  ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
  : body;
if (String.fromCharCode(...data.subarray(0, 4)) !== 'VLT2') throw new Error('Invalid tree data.');
const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
const count = view.getUint32(4, true);
const tableLength = view.getUint16(8, true);
const kinds = JSON.parse(new TextDecoder().decode(data.subarray(10, 10 + tableLength)));
// Archetype (build-trees.py) -> the geometry trees.js grows: 0 plane, 1 feathery (locust), 2 broad evergreen (elm),
// 3 fan palm, 4 bitter orange, 5 canary palm, 6 date palm (both palms), 7 pine (the broad crown, flattened by its
// measured size), 8 cypress (the vase, narrowed by its measured crown)
const GEOMETRY = [0, 1, 2, 3, 4, 3, 3, 0, 2];
const trees = [];
for (let i = 0, o = 10 + tableLength; i < count; i++, o += 8) {
  const x = view.getInt16(o, true) / 4;
  const z = view.getInt16(o + 2, true) / 4;
  const [kind, archetype] = kinds[data[o + 4]];
  const s = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453;
  trees.push({
    x, z, kind, archetype,
    species: GEOMETRY[archetype] ?? 0,
    height: data[o + 5] / 8,
    crown: data[o + 6] / 8,
    pit: (data[o + 7] & 1) === 1,
    yaw: (s - Math.floor(s)) * Math.PI * 2
  });
}

export const REAL_TREES = trees;
